Definition sink_call (chk : CC.cutpoint -> SR.post_spec -> CC.cutpoint -> CA.blocks -> list (expr * Z * Z) -> CA.blocks -> list (expr * Z * Z) -> option CH2.cinfo)
           (i j : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) : bool :=
  match CH2.ret_of G.RETS i k with
  | Some j' => (Nat.eqb j' j && match nth_error G.CPS j with
                               | Some cj => isSome (chk c ps cj (nth i G.BLS []) (nth i FFS []) (nth j G.BLS []) (nth j FFS []))
                               | None => false end)%bool
  | None => false
  end.
